import { validate, validateAsyncApi, applyOverlays, createOverlayRegistry, extractImportSources, getFileCategory, isSnippetExtension, getAST, parseLoadedOverlayDocument, resolveExtends, resolveOverlaysForSpec, normalizeOverlayKey, resolveImportPath, } from '@mintlify/common';
import { isOverlayDocument, validatePathWithinCwd, } from '@mintlify/validation';
import { readFile } from 'fs/promises';
import yaml from 'js-yaml';
import * as path from 'path';
import { formatError } from '../errorMessages/formatError.js';
import { getFileList } from '../fs/index.js';
import { getFileExtension } from '../utils.js';
const MDX_IMPORT_PATTERN = /^import\s/m;
const IMPORT_SOURCE_PATTERN = /import\s+(?:[\w$*{},\s]+?\s+from\s+)?['"]([^'"]+)['"]/g;
const FRONTMATTER_PATTERN = /^\uFEFF?---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/;
const MDX_SCAN_CONCURRENCY = 16;
const FENCE_PATTERN = /^(`{3,}|~{3,})/;
const extractImportSourcesFromContent = (content) => {
    const sources = [];
    let needsAst = false;
    let fence;
    for (const line of content.split('\n')) {
        const trimmed = line.trimStart();
        const fenceRun = FENCE_PATTERN.exec(trimmed)?.[1];
        if (fence !== undefined) {
            if (fenceRun !== undefined &&
                fenceRun.charAt(0) === fence.char &&
                fenceRun.length >= fence.length) {
                fence = undefined;
            }
            continue;
        }
        if (fenceRun !== undefined) {
            fence = { char: fenceRun.charAt(0), length: fenceRun.length };
            continue;
        }
        if (!line.startsWith('import ') && !line.startsWith('import\t')) {
            continue;
        }
        const matches = Array.from(line.matchAll(IMPORT_SOURCE_PATTERN));
        if (matches.length === 0) {
            needsAst = true;
            continue;
        }
        for (const match of matches) {
            const source = match[1];
            if (source) {
                sources.push(source);
            }
        }
    }
    return { sources, needsAst };
};
const getImportSources = (content, filePath) => {
    if (!MDX_IMPORT_PATTERN.test(content)) {
        return [];
    }
    const { sources, needsAst } = extractImportSourcesFromContent(content);
    if (!needsAst) {
        return sources;
    }
    try {
        return extractImportSources(getAST(content, filePath));
    }
    catch {
        return sources;
    }
};
export const categorizeMdxFiles = async (contentDirectoryPath, mdxCandidates, lazyPages) => {
    const importedFiles = new Set();
    const fileImportsMap = new Map();
    const pageScans = new Map();
    const mdxResults = new Array(mdxCandidates.length);
    const queue = mdxCandidates.map((filename, index) => ({ filename, index }));
    await Promise.all(Array.from({ length: Math.min(MDX_SCAN_CONCURRENCY, queue.length) }, async () => {
        let entry = queue.shift();
        while (entry) {
            const { filename, index } = entry;
            const filePath = path.join(contentDirectoryPath, filename);
            try {
                const content = await readFile(filePath, 'utf8');
                const resolvedImports = new Set();
                for (const source of getImportSources(content, filePath)) {
                    const resolved = resolveImportPath(source, filename);
                    if (resolved) {
                        const normalized = resolved.toLowerCase();
                        importedFiles.add(normalized);
                        resolvedImports.add(normalized);
                    }
                }
                fileImportsMap.set(filename.toLowerCase(), resolvedImports);
                if (lazyPages) {
                    pageScans.set(filename, {
                        frontmatter: FRONTMATTER_PATTERN.exec(content)?.[0] ?? '',
                        rssCandidate: content.includes('<Update'),
                    });
                }
                mdxResults[index] = filename;
            }
            catch (error) {
                console.error(formatError(error, filePath, contentDirectoryPath));
            }
            entry = queue.shift();
        }
    }));
    const mdxFilenames = [];
    for (const filename of mdxResults) {
        if (filename !== undefined) {
            mdxFilenames.push(filename);
        }
    }
    const contentFilenames = [];
    const snippets = [];
    const snippetsV2 = [];
    for (const filename of mdxFilenames) {
        const category = getFileCategory(filename, { importedFiles });
        switch (category) {
            case 'snippet':
                snippets.push(filename);
                break;
            case 'snippet-v2':
                snippetsV2.push(filename);
                break;
            case 'page':
                contentFilenames.push(filename);
                break;
        }
    }
    return { contentFilenames, snippets, snippetsV2, fileImportsMap, pageScans };
};
export const listContentFiles = async (contentDirectoryPath, mintIgnore = []) => {
    const mdxCandidates = [];
    const nonMdxFiles = [];
    for await (const filename of getFileList(contentDirectoryPath, contentDirectoryPath, mintIgnore)) {
        const extension = getFileExtension(filename);
        if (isSnippetExtension(extension)) {
            mdxCandidates.push(filename);
        }
        else {
            nonMdxFiles.push({ filename, extension });
        }
    }
    return { mdxCandidates, nonMdxFiles };
};
export const categorizeFilePaths = async (contentDirectoryPath, mintIgnore = [], disableOpenApi, lazyPages, overlayOptions) => {
    const { mdxCandidates, nonMdxFiles } = await listContentFiles(contentDirectoryPath, mintIgnore);
    const { contentFilenames, snippets, snippetsV2, fileImportsMap, pageScans } = await categorizeMdxFiles(contentDirectoryPath, mdxCandidates, lazyPages);
    const staticFilenames = [];
    const openApiFiles = [];
    const asyncApiFiles = [];
    const invalidSpecFiles = [];
    const overlayFiles = [];
    const openApiCandidates = [];
    // Overlays can only be resolved once every file is known, so OpenAPI candidates are
    // buffered and processed after the walk.
    for (const { filename, extension } of nonMdxFiles) {
        switch (extension) {
            case 'json':
            case 'yaml':
            case 'yml':
                const filePath = path.join(contentDirectoryPath, filename);
                const str = await readFile(filePath, 'utf8');
                let obj;
                try {
                    obj = yaml.load(str);
                }
                catch (error) {
                    invalidSpecFiles.push({
                        originalFileLocation: filename,
                        reason: `Invalid JSON or YAML syntax: ${error instanceof Error ? error.message : String(error)}`,
                        kind: 'syntax',
                    });
                    break;
                }
                if (!obj || typeof obj !== 'object')
                    break;
                if (isOverlayDocument(obj)) {
                    const location = normalizeOverlayKey(filename);
                    try {
                        const document = parseLoadedOverlayDocument(obj, location);
                        overlayFiles.push({
                            location,
                            document,
                            resolvedExtends: document.extends == undefined
                                ? undefined
                                : resolveExtends(location, document.extends),
                        });
                    }
                    catch (error) {
                        invalidSpecFiles.push({
                            originalFileLocation: filename,
                            reason: error instanceof Error ? error.message : String(error),
                            kind: 'overlay',
                        });
                    }
                    break;
                }
                const isOpenApi = Object.keys(obj).includes('openapi');
                const isAsyncApi = Object.keys(obj).includes('asyncapi');
                const fileName = path.parse(filename).name;
                if (isOpenApi && !disableOpenApi) {
                    openApiCandidates.push({ filename, fileName, obj, str });
                }
                if (isAsyncApi) {
                    try {
                        const { document: asyncApiDocument } = await validateAsyncApi(str);
                        if (asyncApiDocument) {
                            asyncApiFiles.push({
                                filename: fileName,
                                spec: asyncApiDocument,
                                originalFileLocation: filename,
                            });
                        }
                    }
                    catch (error) {
                        invalidSpecFiles.push({
                            originalFileLocation: filename,
                            reason: error instanceof Error ? error.message : String(error),
                            kind: 'asyncapi',
                        });
                    }
                }
                break;
            default:
                staticFilenames.push(filename);
        }
    }
    const overlayRegistry = createOverlayRegistry({
        explicit: overlayOptions?.explicitOverlays,
        discovered: overlayFiles,
        localSchema: overlayOptions?.localSchema,
        loadLocalDocument: async (normalizedPath) => {
            const { resolvedPath } = validatePathWithinCwd(normalizedPath, contentDirectoryPath);
            const contents = await readFile(resolvedPath, 'utf8');
            return yaml.load(contents);
        },
    });
    for (const { filename, fileName, obj } of openApiCandidates) {
        try {
            const overlays = await resolveOverlaysForSpec(overlayRegistry, filename);
            const overlaid = overlays.length > 0 ? applyOverlays(obj, overlays) : obj;
            if (overlaid == undefined || typeof overlaid !== 'object') {
                throw new Error('Applying overlays produced an invalid OpenAPI document');
            }
            const { schema: openApiDocument } = await validate(overlaid);
            if (openApiDocument) {
                openApiFiles.push({
                    filename: fileName,
                    spec: overlaid,
                    originalFileLocation: filename,
                });
            }
        }
        catch (error) {
            invalidSpecFiles.push({
                originalFileLocation: filename,
                reason: error instanceof Error ? error.message : String(error),
                kind: 'openapi',
            });
        }
    }
    return {
        contentFilenames,
        staticFilenames,
        openApiFiles,
        asyncApiFiles,
        invalidSpecFiles,
        overlayFiles,
        overlayRegistry,
        snippets,
        snippetsV2,
        fileImportsMap,
        pageScans,
    };
};
